import{z as d,x as A,o as t,c as n,q as s,j as l,D as o,d as E,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"二义与左递归","description":"","frontmatter":{"title":"二义与左递归","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ambiguity-leftrec.md","filePath":"cs/ambiguity-leftrec.md","lastUpdated":1791413859000}'),p={name:"cs/ambiguity-leftrec.md"};function c(m,a,h,C,F,f){const r=A("Mermaid");return t(),n("div",null,[a[2]||(a[2]=s('<h1 id="二义与左递归" tabindex="-1">二义与左递归 <a class="header-anchor" href="#二义与左递归" aria-label="Permalink to &quot;二义与左递归&quot;">​</a></h1><div class="epigraph"><p>同一终结串两棵推导树即二义；左递归让最左推导尚未读记号就展开自己，递归下降不停机。</p><footer>—— 据 Chomsky, 1959；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/cfg-grammar">上下文无关文法</a>定义了产生式与推导树，并声明二义必须消、左递归留给分析器课。本课不重写 \\(G=(V,\\Sigma,P,S)\\)。缺口是两件会让下一课递归下降直接翻车的性质：悬空 else 这类二义，以及 \\(E\\to E+T\\) 这类左递归——后者要在文法上改写成右递归或循环，分析函数才停。FIRST 表下一课才系统算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二义：存在 \\(w\\) 有两棵不同的最左推导树。运算符优先级没写进文法时 <code>1+2*3</code> 两棵；<code>if</code>–<code>else</code> 与内层 <code>if</code> 配对两可。语义要唯一 AST，必须改产生式（分层 \\(E\\)、\\(T\\)、\\(F\\)）或在后课 LR 里用优先级声明消冲突。改写后语言应不变，树的形状按语言约定（左结合即左深树）。</p><p><span class="marginnote">数字实例：不写优先级的文法里，<code>1+2*3</code> 有两棵树——按 (1+2)<em>3 求值得 9，按 1+(2</em>3) 求值得 7。串一模一样，语义差出一截：这就是为什么语言标准必须用分层产生式或优先级声明把树钉死成一种。</span></p><p>左递归：\\(A\\stackrel{+}{\\Rightarrow}A\\alpha\\)。递归下降 <code>parseA</code> 先调 <code>parseA</code>，前瞻未消耗。消除：把 \\(A\\to A\\alpha\\mid\\beta\\) 改成 \\(A\\to\\beta A&#39;\\)，\\(A&#39;\\to\\alpha A&#39;\\mid\\varepsilon\\)（右递归），或写成 <code>parseA</code> 里先吃 \\(\\beta\\) 再循环吃 \\(\\alpha\\)。间接左递归要先代换。缺口是识别与改写，不是写完整下降器。</p><p><span class="marginnote">常见误区：初学者觉得「递归下降嘛，文法递归它就递归，很正常」。但左递归的递归发生在<strong>吃掉任何输入之前</strong>——<code>parseA</code> 第一行就调 <code>parseA</code>，参数与输入指针原地不动，每次调用叠一层栈帧直到栈溢出；这和「先吃一个记号再递归」的正常递归（深度有限）有本质区别。</span></p><h3 id="左递归不是二义" tabindex="-1">左递归不是二义 <a class="header-anchor" href="#左递归不是二义" aria-label="Permalink to &quot;左递归不是二义&quot;">​</a></h3><p>左递归文法可以无二义（标准算术分层仍左递归）。二义文法也可以无左递归。两件事都碍分析，原因不同：一棵树 vs 停机。</p><p><span class="marginnote">龙书 4.3 节消除左递归、提取左公因子。Chomsky 层级不管二义；二义是分析器工程。Yacc 的优先级是后课 LR 的出口，本课以改写文法为主。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对二义：给两棵树，改分层或强制 else 绑定。对左递归：找出环 \\(A\\Rightarrow A\\alpha\\)，套标准改写。提取公因子 \\(A\\to\\alpha\\beta\\mid\\alpha\\gamma\\) 变成 \\(A\\to\\alpha B\\)，供后课 LL(1) 一眼看穿。</p>',13)),(t(),l(i,null,{default:o(()=>[B(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20AMB%5B%22%E4%BA%8C%E4%B9%89%EF%BC%9F%E6%94%B9%E5%86%99%E6%88%96%E5%90%8E%E8%AF%BE%E6%B6%88%E5%86%B2%E7%AA%81%22%5D%0A%20%20CFG%20--%3E%20LR%5B%22%E5%B7%A6%E9%80%92%E5%BD%92%EF%BC%9F%E6%94%B9%E5%8F%B3%E9%80%92%E5%BD%92%E6%88%96%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20LR%20--%3E%20RD%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%80%92%E5%BD%92%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"语言是否仍同一：改写是语法变换，应保持 \\(L(G)\\)。优先级分层改变的是树，不是串集合——若原文法二义，串集合本就对多棵树。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("改写后非终结符变多，推导变长，AST 仍应压缩分层节点——"),e("a",{href:"/cs/ast"},"抽象语法树"),E(" 再丢。本课不建树。也不要把「有二义所以不是 CFG」：CFG 可以二义；无二义 CFG 才适合当程序语言定义。")],-1)),a[6]||(a[6]=e("p",null,"左递归对 LR 无妨，对 LL 有妨。下一课是下降，故本课必须先改。",-1)),a[7]||(a[7]=e("p",null,"左递归消除在文法上到底动了什么？以 \\(E\\to E+T\\mid T\\) 为例，改写只换「展开方向」，串集合一字不变：",-1)),(t(),l(i,null,{default:o(()=>[B(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E5%8E%9F%E4%BA%A7%E7%94%9F%E5%BC%8F%20E%20%E2%86%92%20E%20%2B%20T%EF%BC%8C%E6%88%96%20E%20%E2%86%92%20T%EF%BC%9A%E5%85%88%E5%B1%95%E5%BC%80%E8%87%AA%E5%B7%B1%22%5D%20--%3E%20INF%5B%22parseE%20%E6%9C%AA%E8%AF%BB%E4%BB%BB%E4%BD%95%E8%AE%B0%E5%8F%B7%E5%B0%B1%E5%86%8D%E8%B0%83%20parseE%EF%BC%8C%E6%97%A0%E9%99%90%E9%80%92%E5%BD%92%22%5D%0A%20%20OLD%20--%3E%20NEW%5B%22%E6%94%B9%E5%86%99%E6%88%90%20E%20%E2%86%92%20T%20E%E2%80%B2%EF%BC%8CE%E2%80%B2%20%E2%86%92%20%2B%20T%20E%E2%80%B2%EF%BC%8C%E6%88%96%20%CE%B5%EF%BC%9A%E5%85%88%E5%90%83%20T%20%E5%86%8D%E5%B1%95%E5%BC%80%22%5D%0A%20%20NEW%20--%3E%20STOP%5B%22parseE%20%E5%90%83%E4%B8%80%E4%B8%AA%20T%20%E5%90%8E%E8%BF%9B%E5%85%A5%E5%BE%AA%E7%8E%AF%E5%90%83%20%2B%20T%EF%BC%8C%E5%BF%85%E7%84%B6%E5%81%9C%E6%9C%BA%22%5D%0A%20%20NEW%20--%3E%20SAME%5B%22%E8%AF%AD%E8%A8%80%E4%B8%8D%E5%8F%98%EF%BC%9A%E4%BB%8D%E6%98%AF%E5%85%A8%E4%BD%93%E5%8A%A0%E6%B3%95%E8%A1%A8%E8%BE%BE%E5%BC%8F%E4%B8%B2%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p><span class="marginnote">直觉类比：悬空 else 的「就近绑定」像食堂排两列队时新来的人总被最近的队拉走——<code>if a then if b then s1 else s2</code> 里，else 自动跟内层的 <code>if b</code> 配对。C、Java 都把这条写进规范，于是两棵树里只剩「绑内层」那棵合法。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 FIRST/FOLLOW，不移进归约。不处理通用二义检测（那是不可判定的问题族边缘，点名：任意 CFG 是否二义不可判定，程序语言用手改）。后课默认：交给递归下降的文法无左递归、尽量无二义。下降器把最左推导写成函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二义 = 一串多树；用分层或绑定规则消。</li><li>左递归使下降不停机；改写成右递归或循环。</li><li>两性质独立；下一课才写 <code>parseA</code>。</li><li>出处：Aho et al., 龙书第 4 章；Chomsky, 1959。</li></ul>',5))])}const D=d(p,[["render",c]]);export{T as __pageData,D as default};
